from itertools import permutations

def calculate_xor_sequence(sequence):
    xor_result = sequence[0]
    for i in range(1, len(sequence)):
        xor_result = xor_result ^ sequence[i]
    return xor_result

def is_valid_sequence(sequence, p):
    xor_result = calculate_xor_sequence(sequence)
    total_sequence = ''.join(map(str, sequence))
    return xor_result == 0 and total_sequence % p == 0

def find_valid_sequence(a, p):
    valid_sequences = set()
    for perm in permutations(range(1, len(a) + 1)):
        if all(a[i] != a[i + 1] for i in range(len(a) - 1)):
