def min_redundancy_effects(activity_intervals):
    sort_cluster = []
    start, end, maintain = 0, 1, 0
    # Separate disconnected intervals in "activity_intervals" list and find their minimum spanning tree.
    for i in sorted(activity_intervals):
        if maintain:
            end, end_d, temp_end, temp_end_d = end_d, 0, end, end - start
            if i[0] >= temp_end:
                maintain = 0
        if not maintain:
            start, start_d = i, i[1] - i[0]
        end_d, temp_start = end_d, 0
        if i[0] >= end:
            end += i[1] - i[0]
            sort_cluster.append([start, temp_end])
            if temp_start + end_d > 0:
                maintain = 1
            if ignore == 'denoise':
                sort_cluster.extend([end_d, i[1] - end_d])
            if ignore == 'clustering' and start_d + temp_end_d > 0:
                sort_cluster.extend([start_d, i[1] - start_d])
