def count_sum_to_k(l):
    """Calculate the number of combinations such that their sum is k, also the count from 1 to L."""
    s = sum(l)
    ps = sorted(list(reversed(sorted([sum(l[:i+1]) for i in range(len(l))) ])))
    d = {1 : 1}
    def dp(i, s):
        if i == len(l) - 1:
            return s and d.get(s - l[i]) % mod
        total = 0
        while (j := ps.index(s - l[i])] == len(ps)):
            total += dp(j, s - l[i], d)
        return total % mod
    return sum(dp(j, s - l[0]) for j in range(len(l) - 1)) * len(ps)

