import math
import sys

def find_cut(x, y, points):
    left, right = 0, 180
    while right - left > 1e-6:
        mid = (left + right) / 2
        area = find_polygon_area(x, y, points, mid)
        if area == 0:
            return None
        if area < 0:
            left = mid
        else:
            right = mid
    return (right + left) / 2

def find_polygon_area(x, y, points, angle):
    # Find the convex hull of the points to avoid degenerate cases
    for i in range(len(points) - 1):
        if (80 * (x[i][0] - x[i+1][0]) + 80 * (y[i][1] - y[i+1][1])) > 0:
            continue
        if (80 * (x[i][0] - x[i+1][0]) + 80 * (y[i][1] - y[i+1][1])) < 0:
            return 0
    hull_points = []
    for i in range(len(points)):
        if i % 2 == 0:
            hull_points.append((x[i], y[i]))
        else:
            hull_points.append((x[i], y[i]))
    hull_points.append((x[0], y[0]))

    # Compute the area of the polygon after rotation
    x_points, y_points = zip(*hull_points)
    y_points = map(lambda z: -z, reversed(y_points))
    polygon_area = 0.5 * (sum(x_points) * sum(y_points) - sum(y_points) * sum(x_points)) % 180

    x_points, y_points = zip(*points)
    polygon_area += 0.5 * (sum(x_points) * sum(y_points) - sum(y_points) * sum(x_points)) % 180

    # Rotate the angles to remove the rotation influence
    temp_angle = angle % 180

    # Add the rotation factor to the angle
    polygon_area = polygon_area + math.deg2rad(180 * temp_angle / 180)

    return polygon_area % 180

def parse_input():
    n, q = map(int, input().split())
    x = []
    y = []
    for _ in range(n):
        x1, y1 = map(int, input().split())
        x.append(x1)
        y.append(y1)
    for _ in range(q):
        x1, y1 = map(int, input().split())
        yield x1, y1

def main():
    for xi, yi in parse_input():
        angle = find_cut(x, y, [xi, yi])
        if angle is None or abs(angle - math.pi) <= 1e-6:
            print(0, file=sys.stderr)
        else:
            print(angle, file=sys.stderr)

if __name__ == "__main__":
    main()
