import math
from collections import defaultdict

def is_perfect_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def divide_array(arr, index, p):
    for i in range(index, len(arr)):
        if arr[i] % p == 0:
            arr[i] //= p
    return arr

def multiply_array(arr, index, p):
    for i in range(index, len(arr)):
        arr[i] *= p
    return arr

def f(arr):
    n = len(arr)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for j in range(1, n + 1):
        for k in range(j):
            if is_perfect_square(arr[k] * arr[j]):
                dp[j] = min(dp[k] + 1, dp[j])
        for k in range(n - j + 1):
            if n - j + k >= j:
                if is_perfect_square(arr[k] * arr[n - j + k]):
                    dp[j + k] = min(dp[k] + 1, dp[j])
            else:
                break

    return dp[n]

