    Solves the problem by checking if there's a way to satisfy the conditions.
    """
    sieve = [True] * (n + 1)
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n + 1, i):
                sieve[j] = False
    not_prime_sum = sum(n for i, n in enumerate(sieve) if not n)

    if not_prime_sum < len(sequence):
        return "No"
    else:
        return "Yes\n" + str(len(sequence) - not_prime_sum) + "\n" + " ".join(map(str, sequence))
