from collections import defaultdict

def solve(n, p, seq):
    # Create a dictionary to count the occurrences of each number in the sequence
    count = defaultdict(int)
    for num in seq:
        count[num] += 1

    # Check if 0 can never be in the sequence
    if 0 in count and p % count[0] == 0:
        return "No"

    # Try to remove the minimum number of elements to satisfy the conditions
    total_xor = 0
    zero_count = 0
    for num in seq:
        if num == 0:
            zero_count += 1
        else:
            total_xor ^= num
    if zero_count > 2:
        return "No"

    # If gcd(total_xor - new_xor) != 1, an even popping up will never work
    gcd = total_xor
    for new_xor in range(1, p):
        if (total_xor - new_xor) % gcd != 0 or new_xor % p == 0 or new_xor == 0:
            gcd //= gcd
            if gcd < 2:
                gcd = 1
            return "No"

    # Remove non-even multiples of p
    for num in seq[len(last_subset)]:
        total_xor ^= num
        if total_xor % p == 0:
            last_subset.append(num)

    # If there are no non-even multiples of p, remove the extra '0' element
    if not last_subset:
        return "No"

    return "Yes"

