import math

MOD = 998244353

def power(x, n):
    if n == 0:
        return 1
    elif n % 2 == 0:
        y = power(x, n // 2)
        return (y * y) % MOD
    else:
        y = power(x, n - 1)
        return (x * y) % MOD

def inv(a, m):
    return power(a, m - 2) % m

def ncbi(n, c):
    result = 1
    for k in range(c):
        result = result * (n - k) % MOD
    p = power(n, MOD - 2)
    result *= power((MOD + 1) // MOD, MOD - c)
    result *= inv(MOD + 1, MOD)
    result = (result * inv(p, MOD)) % MOD
    return result

def process(n, k):
    if n == 1:
        return power(k, k)
    else:
        return (int(n ^ 1) * ncbi(n, k)) % MOD

def solve(n, k, chocolate_lengths):
    total_length = sum(chocolate_lengths)
    number_of_divisions = process(total_length, k)
    return abs(number_of_divisions % MOD)

