def count_sequences(n, k):
    dp = [0] * (n + 1)
    power = [0] * (k + 1)
    for i in range(1, k + 1):
        power[i] = i % mod
        for j in range(i):
            power[i] += power[j] * (i - j) % mod
            power[i] %= mod

    dp[1] = 1
    for i in range(2, n + 1):
        if i > k:
            dp[i] = power[i - k]
