from collections import defaultdict

def solve(scenario_requests, queries):
    n, m, k, q = map(int, input().split())
    scenario_requests = list(map(lambda x: list(map(int, x.split())), input().split()))
    toys_per_child = defaultdict(set)

    for request in scenario_requests:
        toys_per_child[request[0]].add(request[1])

    toy_requests = sorted(queries, key=lambda x: x[1])

    waiting_children = {i for i in range(1, n + 1) if i not in toys_per_child}
    started_playing_child = set()
    toys_now_in_play = {i for i in range(1, m + 1)}
    crying_set = set()

    for i in range(q):
        x, y = toy_requests[i]
        if toys_in_play := toys_per_child[x]:
            toys_now_in_play.remove(toys_in_play.pop())

            if not toys_in_play:
                toys_now_in_play.add(y)
                crying_set.add(x)
                waiting_children.remove(x)
                waiting_children.add(x)

        child_playing = toys_per_child[x].pop() if toys_per_child[x] else None

        if child_playing is None:
            toys_now_in_play.add(y)
            if not toys_now_in_play.issubset(toys_per_child):
                crying_set.add(x)
                waiting_children.remove(x)
                waiting_children.add(x)
            else:
                if y in toys_per_child:
                    toys_per_child[x].add(y)
                waiting_children.add(x)

        if child_playing:
            toys_per_child[child_playing].discard(y)

    for x, y in queries:
        if x in waiting_children and y in toys_per_child[x]:
            crying_set.add(x)
        crying_set.discard(y)

    return len(crying_set)

