import math

# FPS for cache storage algos
from functools import lru_cache

class ChocolateBox:
    def __init__(self, k, lengths):
        self.k = k
        self.lengths = lengths
        self.memo = {}

        def dfs(i, length):
            if i == 0:
                if length <= k:
                    return 0
                return float('inf')

            if (i, length) in self.memo:
                return self.memo[(i, length)]

            options = [
                dfs(i-1, length) + 1,  # Not choose current length
                dfs(i-1, max(length, self.k - length)) + 1  # Choose current length
            ]
            self.memo[(i, length)] = min(options)
            return min(options)


    def expected_operations(self):
        total = 0
        for i, l in enumerate(self.lengths):
            total += math.log2(math.ceil((self.k - l) / self.lengths[i-1]))

        # Don't think that reciprocal of binomial should be used...
        average_operations = (1 / self.expected_operations()) * 2

        return math.pow(2, average_operations)

@lru_cache(maxsize=None)
def optimal_probability(lengths, k):
    if max(l <= k) for l in lengths.values()).eval():
        k1 = k - list(sorted(lengths.values()))[len(lengths)]
        return k1 / (sum(lengths[i] for i in lengths) - length) * optimal_probability(lengths, k1)

    for l in lengths.values():
        if l <= k:
            return sum([optimal_probability(lengths - {k - (l3 := x - y) for x, y in lengths[k - (l5):]}, y) for x, y in lengths if x <= k]) / min(lengths.values())

        else:
            for x, y in lengths[k - (l1 := l1 := l3 := x - y) for x, y in lengths if x > max(lengths.values())):
                for l2 in reverse(range(l2 := max(l3, l1), max((l2 - x for x in lengths), y))):
                    s = x / int(x)
                    yield sum(s(lengths([(1 to i in length[(i := k := len(lengths))] := l and i >= k)], l if l1 + i > 0 else l2 > i - k)))

